// Generated by `hapi openapi init lauras-trip`, then completed as the local
// entry-point layer. Business state remains in TripService.
import { tripService } from "./TripService";

function unavailable(body: unknown) {
  return new Response(JSON.stringify(body), {
    status: 409,
    headers: { "content-type": "application/json" },
  });
}

export default {
  listFlights: () => tripService.listFlights(),
  selectFlight: (_params: Record<string, string>, body: { flightId: string }) => tripService.selectFlight(body.flightId),
  bookFlight: (_params: Record<string, string>, body: { flightId: string; travellerId: string }) => tripService.bookFlight(body.flightId, body.travellerId),
  modifyFlight: (params: { flightId: string }, body: { departureDate: string }) => tripService.modifyFlight(params.flightId, body.departureDate),
  cancelFlight: (params: { flightId: string }) => tripService.cancelFlight(params.flightId),
  listHotels: () => tripService.listHotels(),
  selectHotel: (_params: Record<string, string>, body: { hotelId: string }) => tripService.selectHotel(body.hotelId),
  bookHotel: (_params: Record<string, string>, body: { hotelId: string; travellerId: string }) => {
    const result = tripService.bookHotel(body.hotelId, body.travellerId);
    return "unavailable" in result ? unavailable(result) : result;
  },
  cancelHotel: (params: { hotelId: string }) => tripService.cancelHotel(params.hotelId),
  listTransfers: () => tripService.listTransfers(),
  bookTransfer: (_params: Record<string, string>, body: { transferId: string }) => tripService.bookTransfer(body.transferId),
  getItinerary: () => tripService.itinerary(),
  resetDemo: () => tripService.reset(),
};
